INSERT INTO `questions` (`id`, `exam_id`, `question_text`, `question_type`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `created_at`) VALUES
(117, 109, '1.Jelaskan pengertian hadist mutawatir ,beserta syarat syarat hadist mutawatir ,dan 2 macam hadist mutawatir!!\r\n2.Jelaskan pengertian hadist Ahad dan macam macam hadist Ahad secara jelas dan lengkap!!\r\n3.Hadist berdasarkan kualitas (derajat) suatu hadist ada 3,jelaskan masing masing pengertian hadist tersebut beserta syarat syarat nya secara lengkap dan jelas!!\r\n4.jelaskan makna hadist muttashil dan 2 syarat hadist muttashil!!\r\n5.Jelaskan makna hadist maudu\' dan sebutkan 3 diantara ciri hadist maudu\'!!\r\n6.Sebutkan 5 macam hadist dhaif disebabkan perawinya bermasalah!!\r\n7.Apa perbedaan hadist mutawatir istilahy dan hadits mutawatir ghair istilahy!!\r\n8.Sebutkan 2 macam hadist dhaif disebabkan ada kejanggalan dan kecacatan!!\r\n9.أمرنا أن نقرأ بفاتحة الكتاب\r\nHadist ini diriwayatkan oleh Abu daud dengan sanad abu Walid Attayalisi-Hammam-Qatadah,-Abu nadrah dan said ,semua perawi tersebut berasal dari Basrah dan tidak ada yang meriwayatkan dari kota lain,hadist tersebut dinamakan apa??\r\n10.Sebutkan 5 macam hadist dhaif disebabkan adanya sanad yang terputus!!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-02 06:54:55'),
(123, 112, '1.Ada berapakah rukun kalimat  لا إله إلا الله الله??jelaskan masing masing rukun tersebut dengan jelas dan lengkap!\r\n2.Apa makna yang benar dari kalimat \"لا معبد بحق إلا الله\"!\r\n3.sebutkan 7 syarat kalimat tauhid لا إله إلا الله?\r\n4.Ada berapa rukun kalimat  أن محمد الرسول الله??jelaskan secara lengkap masing masing rukun tersebut!!\r\n5.sebutkan 3 diantara kewajiban seorang muslim kepada rasulullah shallallahu alaihi wasallam??\r\n6.Meyakini dalam hati ,di ucapkan dengan lisan,dan dibuktikan dengan amal perbuatan ,bertambah dengan ketaatan dan berkurang dengan kemaksiatan adalah makna dari??\r\n7.Berserah diri kepada Allah,dengan mentauhidkannya,mentaati Apa yang Allah perintahkan,dan menjauhi apa yang dilarangnya,mencintai kamu muslimin dan berlepas diri dari syirik dan pelakunya adalah makna dari??\r\n8.Tulislah 2 diantara keimanan yang benar kepada Allah??\r\n9.Terdapat dalam Qur\'an surat Apakah yang merupakan dalil bahwa segala sesuatu yang disembah selain Allah adalah batil??\r\n10.Tulis 3 saja diantara buah atau manfaat \"iman\" dalam kehidupan manusia!!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-02 10:51:15'),
(124, 113, '1.Apa pengertian ilmu mustolahul hadist??\n2.Apa makna hadist ??\n3.Aps makna matan hadist?\n4.Apa makna sanad hadist ??\n5.Apa pengertian hadist Ahad??\n6Ada berapa macamkah hadist Ahad??\n7.Apa pengertian hadist muttashil dan sebutkan syarat hadist muttashil??\n8.Apa pengertian hadist musnad dan kitab musnad apakah yang paling terkenal??\n9.Dinamakan hadist apakah yang jumlah perawi nya 3 atau 4 orang perawi??\n10.Dinamakan hadist apakah yang jumlah perawi 2 atau 3 orang perawi ??', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-02 13:42:49'),
(126, 115, '1.Qur\'an surat Ali Imran ayat 19 merupakan dalil bahwa agama disisi Allah adalah ??\r\n2.Dalam Qur\'an surat Ali Imran Ayat 85 Allah Subhana wata\'ala menyatakan bahwa barang siapa mencari agama selain Islam maka agama tersebut ......dan diakhirat mereka termasuk orang yang.......\r\n3.Berserah diri pada Allah,mentauhid kan Allah,mentaati perintah dan larangan Allah,mencintai kaum muslimin dan berlepas diri dari syirik dan pelakunya adalah makna dari??\r\n4.Tulis 5 rukun atau pondasi islam??\r\n5.Bagaimana seharusnya sikap kamu setelah Allah menganugerahkan mu sehingga terlahir sebagai \r\nseorang muslim!!\r\n6.Apa dua pedoman hidup yang apabila seorang muslim berpegang teguh kepada keduanya tidak akan tersesat selamanya dan akan selamat didunia dan \r\nakhirat??\r\n7.Tulislah satu saja bukti bahwa Islam adalah agama yang paling benar??\r\n8.Tulislah makna yang benar dari kalimat syahadat !!\r\n9.Kunci surga yaitu??\r\n10. Tulislah salah satu bukti atau tanda tanda adanya Allah !!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-02 14:11:51'),
(127, 116, '1.Qur\'an surat Muhammad ayat 19 adalah dalil perintah untuk bertauhid,jelaskan makna tauhid dan tulislah 2 saja diantara keutamaan tauhid!\n2.Para ulama membagi tauhid menjadi tiga,jelaskan masing masing pengertiannya secara jelas dan lengkap!\n3.Qur\'an surat Annahl ayat 36 adalah dalil bahwa perkara pertama yang Allah wajibkan atas manusia yaitu??\n4.Jelaskan makna ibadah beserta dalilnya !!\n5.Sebutkan 2 syarat diterimanya ibadah !!\n6.Amalan ibadah harus berdasarkan dalil yang terdapat dalam..??\n7.Hukum asal ibadah adalah........sampai ada dalil yang.....\n8.Apa makna bid\'ah??\n9.Qur\'an surat An-nisa ayat 36 adalah dalil larangan berbuat syirik,jelaskan makna syirik dan sebutkan 3 macam syirik !!\n10.Apa pengertian syirik Akbar dan sebutkan 4 macam termasuk syirik Akbar!!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-02 14:34:16'),
(131, 120, '1.Hadist ditinjau dari kualitas (derajat )hadist ada 3 macam,jelaskan masing masing pengertian hadist tersebut beserta syarat syarat nya!!\n2.Jelaskan makna hadist mutawatir dan sebutkan syarat syarat hadist mutawatir secara jelas dan lengkap!!\n3.Jelaskan makna hadist Ahad dan macam macam hadist Ahad secara jelas dan lengkap!!\n4.Jelaskan pengertian hadist musnad dan kitab musnad apakah yang paling terkenal??\n5.JeLaskan makna sahabat,tabi\'in dan tabi\'ut tabi\'in !!\n6. من كذب علي متعمدا فليتبوأ مقعده من النار\nJelaskan alasan kenapa hadist tersebut dinyatakan sebagai hadist mutawatir lafadz dan makna!!\n7.Sebutkan 5 macam hadist dhaif disebabkan adanya sanad yang terputus!!\n8.Apa perbedaan hadist Gharib muthlaq dan hadist Gharib nisbi!!\n9.Sebutkan 2 macam hadist dhaif dari sisi matan hadist!!\n10.لا يؤمين أحدكم حتى أكون أحب إليه من والده وولده و الناس أجمعين\nHadist tersebut diriwayat kan dari Anas bin malik dan abu hurairah radhiyallohu \'anhu,lalu dari sahabat Anas bin malik hadist ini diriwayatkan oleh Qatadah dan Abdul aziz bin suhaib,lalu dari Qatadah diriwayatkan oleh syu\'bah dan said,lalu dari jalur Abdul Aziz diriwayatkan oleh perawi Ismail bin \'ulaiyah dan Abdul warist bin said ,dinamakan apakah hadist tersebut??', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-02 15:05:53'),
(132, 122, '1.Jelaskan definisi(pengertian) malaikat secara bahasa dan istilah??\r\n2.Sebutksn nama nama malaikat dan ciri fisiknya!!\r\n3.Dalam surat apa Allah Subhana wata\'ala membantah orang orang yahudi yang mengatakan bahwa adalah banaatullah??\r\n4.Apa itu Rasi dan gravitasi menurut sahabat Ibnu Abbas??\r\n5.Apakah kehidupan manusia dan jin sama??Jelaskan !!\r\n6.Ada dua pendapat terkait makhluk perusak bumi,Sebutkan!!\r\n7.Apa pendapat Abdullah Ibnu Amr terkait Hin dan Bin??\r\n8.Dalam surat apa Allah mengabarkan malaikat bahwa Allah akan menjadikannya Kholifah di bumi??\r\n9.Apa alasan malaikat menanyakan tujuan diciptakannya Adam??\r\n10.Sebutkan 4 kehormatan yang dimiliki Adam!!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-04 03:29:32'),
(133, 123, 'Malaikat adalah ?', 'multiple_choice', 'Makhluk Allah', 'Pembawa bencana', 'Pembawa kabar', 'A dan C benar.', 'D', '2025-10-04 06:43:08'),
(134, 123, 'Dibawah ini adalah sifat perangai malaikat,kecuali?', 'multiple_choice', 'Tidak memiliki sifat laki laki dan perempuan', 'Tidak makan,minum,dan tidak menikah.', 'Suka tidur,main main dan malas', 'Tidak bosan,tidak capek dan tidak tidur', 'C', '2025-10-04 06:43:08'),
(135, 123, 'Sifat fisik yang dimiliki malaikat adalah??', 'multiple_choice', 'Memiliki sayap', 'Memiliki 2 bola mata seperti bintang', 'Bisa berubah menjadi manusia', 'Semua benar', 'D', '2025-10-04 06:43:08'),
(136, 123, 'Makhluk makhluk yang ketika ditiup sangkakala tetap kekal adalah makhluk?', 'multiple_choice', 'Hewan,manusia,langit,bumi dan bintang', 'Neraka,surga،bintang,tumbuhan dan hewan.', 'Manusia,Qolam,lauhul Mahfudz,langit,dan Arsy.', 'Surga,neraka,kursi Arsy,Qolam,lauhul Mahfudz dan sangkakala.', 'D', '2025-10-04 06:43:08'),
(137, 123, 'Sifat dan akhlak malaikat adalah ??', 'multiple_choice', 'Pemalu,terpuji dan baik.', 'Selalu menyombongkan diri', 'Sesat', 'Durhaka', 'A', '2025-10-04 06:43:08'),
(138, 123, 'Nama lain malaikat Jibril adalah?', 'multiple_choice', 'Al Kirom wal barru', 'Ruuhul qudus', 'Muaqibat', 'Malakul jibal', 'B', '2025-10-04 06:43:08'),
(139, 123, 'Dalil tentang malakul maut terdapat dalam surat?', 'multiple_choice', 'Alqolam ayat 5', 'Albaqarah ayat 17', 'Assajdah ayat 11', 'Assyura ayat 21', 'C', '2025-10-04 06:43:08'),
(140, 123, 'Dalil tentang makaikat khozanatul Jannah adalah surat?', 'multiple_choice', 'Al insan ayat 12', 'Azzummar ayat 73', 'Al infithor ayat 7', 'Atthoriq ayat 5', 'B', '2025-10-04 06:43:08'),
(141, 123, 'Siapakah makhluk perusak bumi sebelum adanya manusia?', 'multiple_choice', 'Ya\'juz ma\'juz', 'Iblis', 'Hin dan Bin', 'Dajjal', 'C', '2025-10-04 06:43:08'),
(142, 123, 'Apa alasan malaikat menanyakan tujuan diciptakannya Adam??', 'multiple_choice', 'Iri terhadap adam', 'Ingin mengetahui hikmah', 'Tidak mau menerima', 'Benci kepada Adam', 'B', '2025-10-04 06:43:08'),
(143, 124, '1.Sebutkan definisi(pengertian)malaikat secara bahasa??\r\n2.Apa arti Al Kirom Alkatibun??\r\n3.Apa yang dikatakan Abdullah bin Amr terkait Hin dan Bin??\r\n4.Dalam surat apa Allah mengabarkan malaikat bahwa dia akan menjadikan khalifah di bumi??\r\n5.Tulis lima kehormatan yang dimiliki Adam ??', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-04 06:48:04'),
(144, 125, 'Tuliskan biografi singkat pengarang kitab matan tuhfathul athfal!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:02:05'),
(145, 125, 'Ada berapa hukum nun sukun dan tanwin? Sebutkan dan jelaskan secara ringkas!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:02:05'),
(146, 125, 'Ada berapa hukum mim sukun? Sebutkan dan jelaskan secara ringkas!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:02:05'),
(147, 125, 'Disebut apa hukum mim dan nun bertasydid?', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:02:05'),
(148, 125, 'Apa itu lam ta\'rif? Dan jelaskan pembagian hukum lam ta\'rif!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:02:05'),
(149, 125, 'Ada berapa hukum lam fiil dal lam huruf? Sebutkan!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:02:05'),
(150, 125, 'Jika ada dua huruf yang sama maksroj dan sifat (huruf kembar) bertemu, huruf pertama sukun dan huruf kedua berharokat, disebut? \r\nSebutkan rincian hukumnya secara lengkap!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:02:05'),
(151, 125, 'Apa itu mad? Dan apa saja huruf mad?', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:02:05'),
(152, 125, 'Mad itu terbagi menjadi 2, yaitu mad ashli dan mad far\'i. Apa nama lain dari mad ashli? Jelaskan apa itu mad ashli dan apa syarat terjadinya mad?', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:02:05'),
(153, 125, 'Apa itu mad far\'i? dan sebutkan pembagian mad far\'i!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:02:05'),
(164, 127, 'Tashrifkan \r\nTasrif ushul : \r\n- أَصبَحَ\r\n- جَلَّدَ\r\n- حَافَظَ\r\nFiil amr & nahyi :\r\n- أَدخَلَ\r\n- سَلَّمَ\r\n- قَاتَلَ\r\nIsim fa\'il & isim maf\'ul :\r\n- أَسلَمَ\r\n- قَرَّبَ\r\n- سَافَرَ', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:36:42'),
(165, 127, 'Cari kata \r\n- Apa fiil mudhori majhul untuk dia 1 org pr dari kata : أَصلَحَ\r\n- Apa isim masdar untuk mutsanna (2) dati kata : كَمَّلَ\r\n- Apa fiil madhi untuk kalian 2 org pr dari kata : سَافَرَ\r\n- Apa fiil madhi majhul untuk saya dari kata : أَبعَدَ\r\n- Apa fiil mudhori untuk kami dari kata : شَرَّفَ', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:36:42'),
(166, 127, 'Terjemahkan \r\nKedalam bahasa indonesia :\r\n- أَدخِلُوا\r\n- مُخَرِّجَةٌ\r\n- تُسَاعِدِينَ\r\n\r\nKedalam bahasa arab :\r\n- masuk islamlah kalian laki laki!\r\n- kamu 1 org laki² sedang memotong motong\r\n- aku telah bersungguh-sungguh', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 02:36:42'),
(167, 128, '1.Apa tujuan diciptakannya manusia dan jin??sertakan dalilnya!!\n2.Jelaskan pengertian ibadah??\n3.Apa pengertian syirik??\n4.Apa pengertian thoghut??\n5Apa Tujuan di utusnya nabi dan rasul??', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 05:38:11'),
(168, 129, 'Muqoddimah \r\n- Tuliskan biografi singkat penyusun matan al jazariy!\r\n- Apa saja yang dibahas dialam matan al jazariy?', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 12:57:23'),
(169, 129, 'Makhorijul huruf\r\n- Apa yang dimaksud dengan makhorijul huruf?\r\n- Apa yang dimaksud dengan makhroj muhaqqoq dan muqoddar?\r\n- Tuliskan 10 makhroj dan huruf yang keluar darinya!\r\n- Sebutkan makhroj dari huruf huruf berikut : غ، ع، م، ف، ي', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 12:57:23'),
(170, 130, 'Harokat \r\n- Apa hubungan antara harokat dengan Al jauf\r\n- Harokat terbagi menjadi 2, sebutkan!\r\n- Jelaskan tentang kesempurnaan harokat!\r\n- Sebutkan kesalahan-kesalahan dalam membaca harokat!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 13:08:37'),
(171, 130, 'Shifatul huruf\n- Shifatul huruf terbagi menjadi 2, sebutkan!\n- Shifat lazimah terbagi menjadi 2, sebutkan!\n- Tulis 10 shifatul huruf dan huruf huruf yang tersifati sifat tersebut!\n- Sebutkan shifat dari masing-masing huruf berikut : ر، ل، ز، ض، م', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 13:08:37'),
(172, 130, 'Tajwid \r\n- Ada 3 tipe manusia dalam menanggapi tajwid yaitu muhsin ma\'jur, musiiu ashim dan ma\'dzur, apa yang dimaksud dengan muhsin ma\'jur?\r\n- Ada 2 cara mempelajari Al Quran, sebutlan dan jelaskan!\r\n- Definisi tajwid dalam matan Al jazariy adalah membaca Al Qur\'an sesuai dengan 3 kriteria yaitu?\r\n- Apa itu takalluf dan ta\'ashuf?', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 13:08:37'),
(173, 130, 'Apa itu hamzah washol dan bagaimana cara membacanya?', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-06 13:08:37'),
(174, 131, 'Apa itu makna rabb?', 'multiple_choice', 'Makhluk ciptaan Allah', 'Hamba yang beribadah', 'Yang maha kuasa dan diibadahi.', 'D', 'C', '2025-10-07 07:47:06'),
(175, 131, 'Dengan apa kamu mengetahui rabbmu?', 'multiple_choice', 'Dengan ayat ayatnya dan ciptaanya.', 'Dengan adanya pergantian malam dan siang', 'A dan B benar', 'D', 'C', '2025-10-07 07:47:06'),
(176, 131, 'Untuk apa Allah menciptakan makhluk hidup?', 'multiple_choice', 'Untuk beribadah hanya kepada Allah', 'Untuk menikmati kehidupan dunia tanpa ada aturan.', 'Untuk berbuat kerusakan di bumi', 'D', 'A', '2025-10-07 07:47:06'),
(177, 131, 'وما خلقتُ الجنً و الإنس إلًا ليعبدُوْنَ adalah Qur\'an surat??', 'multiple_choice', 'Almaidah ayat 72', 'Addzariyat ayat 56', 'Albaqarah ayat 100.', 'D', 'B', '2025-10-07 07:47:06'),
(178, 131, 'Menjadikan sesuatu selain Allah sebagai tandingan dalam peribadahan kepada Allah dari??', 'multiple_choice', 'Ibadah', 'Syirik', 'Doa', 'D', 'B', '2025-10-07 07:47:06'),
(179, 131, 'Syirik terbagi kedalam berapa bagian ??', 'multiple_choice', '3 bagian', '1 bagian', '2 bagian.', 'D', 'C', '2025-10-07 07:47:06'),
(180, 131, 'Pengertian ibadah yaitu??', 'multiple_choice', 'Segala sesuatu yang Allah cintai dan ridhoi berupa perkataan dan perbuatan.', 'Meminta sesuatu kepada Allah', 'A dan B salah.', 'D', 'A', '2025-10-07 07:47:06'),
(181, 131, 'Siapa nabi kita??', 'multiple_choice', 'Muhammad bin Abdullah.', 'Muhammad bin ashim', 'Ahmad gulam halim', 'D.', 'A', '2025-10-07 07:47:06'),
(182, 131, 'Tujuan Allah mengurus para rasul adalah??', 'multiple_choice', 'Memperlihatkan surga dan neraka', 'Membagikan makanan pada manusia', 'Menyeru agar manusia agar memurnikan ibadah hanya kepada Allah saja dan menjauhi syirik .', 'D', 'D', '2025-10-07 07:47:06'),
(183, 131, 'Makna لا إله إلّا الله yang benar adalah??', 'multiple_choice', 'Tiada illah yang berhak diibadahi dengan benar kecuali Allah', 'Tidak ada tuhan selain Allah', 'Maha suci Allah lagi maha tinggi', 'D', 'A', '2025-10-07 07:47:06'),
(184, 132, '1.sebutkan nama berhala berhala yang disembah kaumnya nabi Nuh??\r\n2.Coba sebutkan masihan nabi \r\nMuhammad sampai kakek ke-3 nya saja?\r\n3.Ceritakanlah kenapa ada berhala berhala itu pada zaman nabi Nuh??\r\n4.Permintaan dan permohonan itu ada dua macam,sebutkan 2 macam permohonan beserta contohnya??\r\n5.Tulis 5 rukun/pondasi islam !!', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-07 07:53:31'),
(193, 137, 'TINGKATN IMAN\nA. Jelaskan tentang tingkatan iman!\nB. Jelaskan apa yang dimaksud dengan Ashlul iman, wajibatul iman dal al iman almustahab!\nC. Apakah ashlul iman dalam hati dan amal jawarih memiliki keterkaitan? Sebutkan dalilnya!\nD. Bagaimana cara kita mengetahui apakah seseorang mempunyai ashlul iman atau tidak?', 'essay', NULL, NULL, NULL, NULL, NULL, '2025-10-09 06:16:54');
